type MutationCase = {
  readonly id: string;
  readonly path: readonly (string | number)[];
  readonly nextValue: string;
};

function cloneDeck() {
  return structuredClone(PITCH_DECK_FIXTURE);
}

function setAtPath(target: unknown, keyPath: readonly (string | number)[], nextValue: string): void {
  let cursor: any = target;
  for (let index = 0; index < keyPath.length - 1; index += 1) {
    cursor = cursor[keyPath[index] as any];
  }
  cursor[keyPath[keyPath.length - 1] as any] = nextValue;
}

